impl Solution {
    pub fn classify_t_primes(nums: Vec<u64>) -> Vec<bool> {
        let mut result = Vec::new();
        for num in nums {
            if is_t_prime(num) {
                result.push(true);
            } else {
                result.push(false);
            }
        }
        result
    }

    fn is_t_prime(n: u64) -> bool {
        if n <= 1 {
            return false;
        }

        let sqrt_n = (n as f64).sqrt() as u64;

        if sqrt_n * sqrt_n == n && is_prime(sqrt_n as u64) {
            return true;
        }

        false
    }

    fn is_prime(n: u64) -> bool {
        if n <= 1 {
            return false;
        }
        let mut i = 2;
        while i * i <= n {
            if n % i == 0 {
                return false;
            }
            i += 1;
        }
        true
    }
}

